// Keep additive fields optional: runtime responses from older servers are not default-filled.
import { readFileSync, writeFileSync } from 'node:fs'
import openapiTS, { astToString } from 'openapi-typescript'

const schema = JSON.parse(readFileSync('../../docs/protocol/openapi.json', 'utf8'))
const conflict = schema.components.schemas.Conflict
if (!conflict.required?.includes('origin')) delete conflict.properties.origin.default
const header =
  '/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n'
writeFileSync(process.argv[2], header + astToString(await openapiTS(schema)))
